// Synthetic protocol facts only. This entry point opens no HID interface.
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

public static class MouseSensorProtocolTests {
 static int checks;
 static Dictionary<string,object> O(params object[] values){return GearLinkWorker.Obj(values);}
 static void Check(bool result,string message){checks++;if(!result)throw new Exception(message);}
 static void Reject(Action action,string message){bool rejected=false;try{action();}catch(ArgumentException){rejected=true;}catch(IOException){rejected=true;}Check(rejected,message);}
 static Dictionary<string,object> Baseline(int pid){return O("modelPid",pid,"mouseSensorSettings",GearLinkWorker.ParseMouseSensorSettings(pid,new byte[]{18,4,5,0,3,0}),"mouseCalibrationInfo",GearLinkWorker.ParseMouseCalibrationInfo(pid,new byte[]{18,6,0,0,255,255,0,0,0}),"mouseCalibrationLOD",GearLinkWorker.ParseMouseCalibrationLod(pid,new byte[]{18,6,1,0,0,1,4,3,0,0}),"mouseTrackOnGlass",false);}
 static byte[] Build(int pid,string setting,object value,Dictionary<string,object> before){return GearLinkWorker.BuildMouseSensorSetting(setting,value,before,pid);}
 static Dictionary<string,object> Lod(int mode,int lift,int drop,int manual){return O("lodMode",mode,"normalModeLOD",1,"asymmetricLiftValue",lift,"asymmetricDropValue",drop,"manualCalibrationLOD",manual);}
 public static int Main(){try{Run();Console.WriteLine("Mouse sensor protocol: "+checks+" checks passed; native hardware access=false.");return 0;}catch(Exception error){Console.Error.WriteLine("Mouse sensor protocol failure after "+checks+" checks: "+error.Message);return 1;}}
 public static void Run(){
  foreach(int pid in new[]{7546,7548}){
   var before=Baseline(pid);var sensor=(Dictionary<string,object>)before["mouseSensorSettings"];Check((int)sensor["sensorFrameRate"]==13000&&(int)sensor["sensorMode"]==3,"Sensor frame rate decoded without changing mode");var high=GearLinkWorker.ParseMouseSensorSettings(pid,new byte[]{18,4,5,0,0,1});Check((int)high["sensorFrameRate"]==20000&&(int)high["sensorMode"]==0,"Zero dynamic mode is not missing data");
   Check(Build(pid,"sensorFrameRate",20000,before).SequenceEqual(new byte[]{81,49,19,0,3,1}),"FPS write preserves mode and uses SET index19");Check(Build(pid,"sensorFrameRate",13000,before).SequenceEqual(new byte[]{81,49,19,0,3,0}),"13K is wire code zero");Check(GearLinkWorker.MatchesMouseSensorSetting("sensorFrameRate",13000,before)==true&&GearLinkWorker.MatchesMouseSensorSetting("sensorFrameRate",20000,before)==false,"Frame rate readback is not an optimistic cache");
   Check(Build(pid,"mouseCalibrationMode",0,before).SequenceEqual(new byte[]{81,53,0,0,0,255,0,0,0}),"Mode change preserves actual material and K including zero");Check(Build(pid,"mouseTrackOnGlass",true,before).SequenceEqual(new byte[]{81,53,2,0,1}),"Glass switch is a separate one-byte field");Check(GearLinkWorker.MatchesMouseSensorSetting("mouseTrackOnGlass",false,before)==true,"Confirmed false glass state is real readback");
   var values=Lod(1,11,1,0);Check(Build(pid,"mouseCalibrationLOD",values,before).SequenceEqual(new byte[]{81,53,1,0,1,1,11,1,0,0}),"LOD packet contains full native record and zero reserved trigger byte");var manual=Lod(2,4,3,11);Check(Build(pid,"mouseCalibrationLOD",manual,before).SequenceEqual(new byte[]{81,53,1,0,2,1,4,3,0,11}),"Manual level11 is native index11, not converted to millimetres");
   var parsed=GearLinkWorker.ParseMouseCalibrationLod(pid,new byte[]{18,6,1,0,2,1,4,3,1,0});Check((bool)parsed["sensorTriggered"]&&!(bool)parsed["manualLevelInitialized"]&&(int)parsed["manualCalibrationLOD"]==0,"Uninitialized manual zero and actual trigger flag stay separate");
   var caps=new List<string>{"mouseSensorSettings","mouseCalibrationInfo","mouseCalibrationLOD","mouseTrackOnGlass"};var state=O("setCapabilities",new[]{"pollingRate"});GearLinkWorker.AddMouseSensorSetCapabilities(true,pid,state,before,caps);var setters=(string[])state["setCapabilities"];Check(new[]{"pollingRate","sensorFrameRate","mouseCalibrationMode","mouseCalibrationPreset","mouseCalibrationLOD","mouseTrackOnGlass"}.All(s=>setters.Contains(s)),"Set capabilities require successful exact-model getters and preserve existing setters");
   var surfaces=(object[])((Dictionary<string,object>)state["mouseSensorSettingOptions"])["presetSurfaces"];Check(surfaces.Length==24&&surfaces.Cast<Dictionary<string,object>>().Select(s=>(int)s["material"]).Distinct().Count()==24,"24 materials include Off and are not sequential slots");
   ((Dictionary<string,object>)before["mouseCalibrationInfo"])["mode"]=0;state=O("setCapabilities",new string[0]);GearLinkWorker.AddMouseSensorSetCapabilities(true,pid,state,before,caps);Check(!((string[])state["setCapabilities"]).Contains("mouseCalibrationLOD"),"LOD write requires fresh LOD mode readback");Reject(()=>Build(pid,"mouseCalibrationLOD",manual,before),"Preset mode cannot receive LOD setting blindly");
   ((Dictionary<string,object>)before["mouseCalibrationInfo"])["mode"]=255;
   foreach(int material in GearLinkWorker.MouseSensorPresetIds){var packet=Build(pid,"mouseCalibrationPreset",material,before);Check(packet.Length==9&&packet[4]==0&&packet[5]==material&&packet.Skip(6).SequenceEqual(GearLinkWorker.MouseSensorPresetK(material).Select(v=>(byte)v))&&GearLinkWorker.IsMouseSensorWrite(pid,packet),"Every exact preset derives only its functional wire bytes");}
   foreach(int unsupported in new[]{2,3,4,5,6,9,29,254})Reject(()=>Build(pid,"mouseCalibrationPreset",unsupported,before),"Generic or out-of-model material cannot be selected");
   foreach(object bad in new object[]{true,"13000",13000.0,17000,0,20001})Reject(()=>Build(pid,"sensorFrameRate",bad,before),"FPS strict integer discrete domain rejected");
   foreach(var bad in new[]{Lod(1,1,2,0),Lod(1,0,0,0),Lod(2,4,3,0),Lod(3,4,3,1),Lod(1,12,3,1)})Reject(()=>Build(pid,"mouseCalibrationLOD",bad,before),"Invalid active LOD recipe rejected before output");
   var extra=Lod(1,4,3,0);extra["sensorTriggered"]=false;Reject(()=>Build(pid,"mouseCalibrationLOD",extra,before),"Read-only trigger flag cannot be written as a caller field");
   foreach(string field in new[]{"mouseSensorSettings","mouseCalibrationInfo","mouseCalibrationLOD","mouseTrackOnGlass"}){var partial=Baseline(pid);partial.Remove(field);string setting=field=="mouseSensorSettings"?"sensorFrameRate":field=="mouseCalibrationInfo"?"mouseCalibrationMode":field=="mouseCalibrationLOD"?"mouseCalibrationLOD":"mouseTrackOnGlass";object value=setting=="mouseCalibrationLOD"?(object)manual:setting=="mouseTrackOnGlass"?(object)true:setting=="sensorFrameRate"?20000:0;Reject(()=>Build(pid,setting,value,partial),"Missing baseline field never becomes a default");}
   foreach(var request in new[]{new byte[]{18,4,5,0},new byte[]{18,6,0,0},new byte[]{18,6,1,0},new byte[]{18,6,2,0}})Check(GearLinkWorker.IsMouseSensorQuery(pid,request),"Only proven sensor queries are recognized");Check(!GearLinkWorker.IsMouseSensorQuery(pid,new byte[]{81,53,0,0})&&!GearLinkWorker.IsMouseSensorQuery(pid,new byte[]{18,6,3,0}),"Nonquery and unproven query are rejected");
   Check(!GearLinkWorker.IsMouseSensorWrite(pid,new byte[]{81,53,1,0,1,1,4,3,1,0})&&!GearLinkWorker.IsMouseSensorWrite(pid,new byte[]{81,53,0,0,1,0,0,0,0}),"Nonzero reserved trigger and old calibration mode are rejected");
   foreach(int mode in Enumerable.Range(0,5)){var baseline=Baseline(pid);((Dictionary<string,object>)baseline["mouseSensorSettings"])["sensorMode"]=mode;Check(Build(pid,"sensorFrameRate",20000,baseline)[4]==mode,"All proven sensor modes are preserved during FPS-only setting");}
  }
  foreach(int pid in new[]{0,7547,7502,7588}){Reject(()=>GearLinkWorker.ParseMouseSensorSettings(pid,new byte[]{18,4,5,0,0,0}),"Related models cannot inherit parser");Reject(()=>Build(pid,"sensorFrameRate",13000,Baseline(7548)),"Related models cannot inherit setter");Check(!GearLinkWorker.IsMouseSensorQuery(pid,new byte[]{18,6,0,0})&&!GearLinkWorker.IsMouseSensorWrite(pid,new byte[]{81,49,19,0,3,0}),"Transport allowlist is exact-model gated");}
  var beforeModel=Baseline(7548);beforeModel["modelPid"]=7546;Reject(()=>Build(7548,"sensorFrameRate",13000,beforeModel),"Before snapshot cannot belong to another model");
  foreach(var data in new[]{new byte[]{18,4,5,0,0},new byte[]{18,4,4,0,0,0},new byte[]{18,4,5,1,0,0},new byte[]{18,4,5,0,5,0},new byte[]{18,4,5,0,0,2}})Reject(()=>GearLinkWorker.ParseMouseSensorSettings(7548,data),"Short, wrong-header and unknown frame-rate replies rejected");
  foreach(var data in new[]{new byte[]{18,6,0,0,0,0,1,2},new byte[]{18,6,0,0,1,0,0,0,0},new byte[]{18,6,0,0,0,29,0,0,0}})Reject(()=>GearLinkWorker.ParseMouseCalibrationInfo(7548,data),"No short-reply zero-K or generic-mode fallback");
  Reject(()=>GearLinkWorker.ParseMouseGlassTracking(7548,new byte[]{18,6,2,0,2}),"Unknown glass switch does not become false");
  var emptyCaps=O("setCapabilities",new string[0]);GearLinkWorker.AddMouseSensorSetCapabilities(true,7548,emptyCaps,Baseline(7548),new List<string>());Check(((string[])emptyCaps["setCapabilities"]).Length==0,"Capabilities/options never fabricate current hardware getters");
  var offline=O("setCapabilities",new string[0]);GearLinkWorker.AddMouseSensorSetCapabilities(false,7548,offline,Baseline(7548),new List<string>{"mouseSensorSettings"});Check(((string[])offline["setCapabilities"]).Length==0,"Offline cached sensor values cannot enable writes");
  Check(Build(7548,"unprovenCalibrationStart",true,Baseline(7548))==null&&GearLinkWorker.MatchesMouseSensorSetting("unprovenCalibrationStart",true,Baseline(7548))==null,"No legacy 30s Start or guessed cancel command is exposed");
 }
}
